<script setup lang="ts">
import {ref,watch} from 'vue'
const props=defineProps<{rows:any[];portal:(path:string,body?:any)=>Promise<any>;request:(path:string,body?:any)=>Promise<any>}>()
const emit=defineEmits<{changed:[]}>()
const open=ref(false),ids=ref<number[]>([]),target=ref(''),reason=ref(''),people=ref<any[]>([]),page=ref(1),count=ref(0),search=ref(''),busy=ref(false),error=ref(''),message=ref(''),requestId=ref(crypto.randomUUID())
watch(()=>props.rows,()=>{ids.value=[];requestId.value=crypto.randomUUID()})
watch([ids,target,reason],()=>{requestId.value=crypto.randomUUID()},{deep:true,flush:'sync'})
async function directory(){busy.value=true;error.value='';try{const data=await props.portal(`isolation/setters/?page=${page.value}&search=${encodeURIComponent(search.value)}`);people.value=data.results;count.value=data.count}catch(e:any){error.value=e.message}finally{busy.value=false}}
async function submit(){busy.value=true;error.value='';message.value='';try{const selected=props.rows.filter(row=>ids.value.includes(row.id));const setter=target.value==='none'?null:Number(target.value);const items=await Promise.all(selected.map(async row=>({id:row.id,revision:row.revision,...(setter===null?{}:{proof:(await props.portal('isolation/setters/',{prospect_id:row.id,setter_id:setter})).proof})})));const result=await props.request('work-queue/bulk-assign/',{request_id:requestId.value,setter_id:setter,reason:reason.value,items});message.value=`${result.count} prospect(s) traité(s).`;emit('changed')}catch(e:any){error.value=e.message}finally{busy.value=false}}
</script>
<template><section><button class="secondary" :disabled="busy" @click="open=!open;if(open)directory()">{{open?'Fermer les affectations en lot':'Affecter plusieurs prospects'}}</button><section v-if="open"><h4>Affectation de la page courante (25 maximum)</h4><p>Tout le lot est enregistré ou refusé. Une fiche déjà affectée à la cible ou modifiée entre-temps bloque le lot. Les filtres et changements de page effacent la sélection.</p><p v-if="error" role="alert">{{error}}</p><p v-if="message" role="status">{{message}}</p><button class="secondary" :disabled="busy" @click="ids=rows.map(row=>row.id)">Sélectionner cette page</button><button class="secondary" :disabled="busy" @click="ids=[]">Tout désélectionner</button><label v-for="row in rows" :key="row.id"><input v-model="ids" type="checkbox" :value="row.id" :disabled="busy">{{row.name||row.raw_phone}} · {{row.assigned_setter?.name||'Sans setter'}}</label><form @submit.prevent="page=1;directory()"><label>Rechercher un setter<input v-model="search" :disabled="busy"></label><button class="secondary" :disabled="busy">Rechercher</button></form><form @submit.prevent="submit"><label>Cible commune<select v-model="target" required :disabled="busy"><option value="">Choisir</option><option value="none">Retirer les affectations</option><option v-for="person in people" :key="person.id" :value="String(person.id)">{{person.name}}</option></select></label><span>{{count}} setter(s) · page {{page}}</span><button type="button" class="secondary" :disabled="busy||page===1" @click="page--;directory()">Précédent</button><button type="button" class="secondary" :disabled="busy||page*25>=count" @click="page++;directory()">Suivant</button><label>Motif commun obligatoire<textarea v-model="reason" required maxlength="1000" :disabled="busy"></textarea></label><p>{{ids.length}} prospect(s) sélectionné(s)</p><button class="primary" :disabled="busy||!ids.length||!target||!reason.trim()">Confirmer le lot</button><button type="button" class="secondary" :disabled="busy" @click="$emit('changed')">Recharger la page</button></form></section></section></template>
